//! `vectors/renderer.json` is generated by `spores-render vectors`. Any other
//! implementation (the JS port, the wasm build, a verifier) must reproduce it.

use spores_renderer::{hex, image_hash, render, sin_table_hash, trail, trail_hash, Spore, N, RENDERER_VERSION};

#[test]
fn rust_matches_the_shared_vectors() {
    let v: serde_json::Value = serde_json::from_str(include_str!("../../vectors/renderer.json")).unwrap();
    assert_eq!(v["renderer_version"], RENDERER_VERSION);
    assert_eq!(v["n"], N);
    assert_eq!(v["sin_table_hash"], hex(&sin_table_hash()));
    let cases = v["cases"].as_array().unwrap();
    assert!(cases.len() >= 10);
    for c in cases {
        let seed: [u8; 32] = (0..32)
            .map(|i| u8::from_str_radix(&c["seed"].as_str().unwrap()[2 * i..2 * i + 2], 16).unwrap())
            .collect::<Vec<_>>()
            .try_into()
            .unwrap();
        let edges = c["edges"]
            .as_array()
            .unwrap()
            .iter()
            .map(|e| (e[0].as_u64().unwrap() as u32, e[1].as_u64().unwrap()))
            .collect();
        let sp = Spore::new(seed, c["age"].as_u64().unwrap() as u32, edges);
        let name = c["name"].as_str().unwrap();
        assert_eq!(c["trail_hash"], hex(&trail_hash(&trail(&sp))), "{name} trail");
        assert_eq!(c["image_hash"], hex(&image_hash(&render(&sp))), "{name} image");
    }
}
